import { cx } from "./cx";

export type AvatarSize = "sm" | "md" | "lg";

const sizes: Record<AvatarSize, string> = {
  sm: "w-10 h-10 rounded-[13px] text-[13px]",
  md: "w-14 h-14 rounded-[18px] text-ds-md",
  lg: "w-[104px] h-[104px] rounded-[34px] text-[32px] border-4 border-surface shadow-[0_12px_28px_rgba(13,43,94,0.18)]",
};

interface AvatarProps {
  /** Full name; initials are taken from it. */
  name: string;
  /** Photo URL. Initials show when there is none. */
  src?: string | null;
  size?: AvatarSize;
  /** Background behind the initials; defaults to sky. */
  tint?: string;
  className?: string;
}

export function initials(name: string): string {
  const parts = name
    .replace(/^(dr|mr|mrs|ms|prof)\.?\s+/i, "")
    .split(/\s+/)
    .filter(Boolean);
  return ((parts[0]?.[0] ?? "") + (parts.length > 1 ? parts[parts.length - 1][0] : "")).toUpperCase();
}

export function Avatar({ name, src, size = "md", tint, className }: AvatarProps) {
  const base = cx("flex-none overflow-hidden", sizes[size], className);
  if (src) {
    // eslint-disable-next-line @next/next/no-img-element
    return <img src={src} alt={name} className={cx(base, "object-cover")} />;
  }
  return (
    <span
      role="img"
      aria-label={name}
      className={cx(base, "grid place-items-center font-extrabold text-navy", !tint && "bg-sky")}
      style={tint ? { background: tint } : undefined}
    >
      <span aria-hidden>{initials(name)}</span>
    </span>
  );
}
